<issue_comment>username_1: @username_0 I think you need to use `require.resolve` to get the path to the image.

```js
import React, { Component } from 'react';
import { Image } from 'react-native';

export default class App extends Component {
  state = {
    image: null,
  };

  componentDidMount() {
    this.setState({
      image: require.resolve('../assets/images/image.png'),
    });
  }

  render() {
    return (
      <Image
        style={{ width: 200, height: 200 }}
        source={this.state.image}
      />
    );
  }
}
```
